#include <stdio.h>
#include <string.h>
#include <stdlib.h>

void dec2bin(int num, char *s) {
    int i = 0;
    while (num > 0) {
        s[i++] = (char) (num % 2 + '0');
        num /= 2;
    }

    // strrev(s); // 该函数只能在windows系统使用，OJ一般搭建在Linux系统上，因此无法使用该函数

    int l = 0;
    int r = i - 1;
    while (l < r) {
        char tmp = s[l];
        s[l] = s[r];
        s[r] = tmp;
        l++;
        r--;
    }
}

int main() {
    int n;
    scanf("%d", &n);

    char nBinStr[1000] = {'\0'};
    nBinStr[0] = '0';
    dec2bin(n, nBinStr + 1);

    int len = (int) strlen(nBinStr);

    int countOne = 0;

    for (int i = len - 2; i >= 0; i--) {
        if (nBinStr[i] == '0' && nBinStr[i + 1] == '1') {
            // 从右向左找到了第一组"01"子串，则替换为"10"
            nBinStr[i] = '1';
            nBinStr[i + 1] = '0';

            // 如果第一组"01"子串右边存在1
            if (countOne > 0) {
                // 则将第一组"01"子串的右边部分的'1'要全部集中到尾部
                for (int j = i + 2; j < len; j++) {
                    if (j < len - countOne) {
                        nBinStr[j] = '0';
                    } else {
                        nBinStr[j] = '1';
                    }
                }
            }

            break;
        }

        // 记录第一组"01"子串右边1的个数
        if (nBinStr[i + 1] == '1') {
            countOne++;
        }
    }

    char *endptr;
    int m = strtol(nBinStr, &endptr, 2);

    printf("%d\n", m);

    return 0;
}
